const f = $input.first().json;
const engagement = String(f.engagement || '').trim().toLowerCase();
if (!/^[a-z0-9_-]{1,40}$/.test(engagement)) throw new Error(`Invalid engagement name "${engagement}". Use the name from asm_scope.`);
const SEVS = ['critical', 'high', 'medium', 'low', 'info'];
const minSev = String(f.min_severity || 'Low').toLowerCase();
const days = Math.max(0, Math.min(3650, parseInt(f.period_days, 10) || 0));
const now = new Date();
const stamp = now.toISOString().replace(/[-:]/g, '').replace(/\.\d+Z$/, 'Z');
const report_id = `${stamp}-${Math.random().toString(16).slice(2, 6)}`;
return [{ json: {
  engagement,
  client_name: String(f.client_name || '').trim().slice(0, 120) || engagement,
  period_days: days,
  since: days ? new Date(now.getTime() - days * 864e5).toISOString() : null,
  min_severity: SEVS.includes(minSev) ? minSev : 'low',
  hide_fp: f.hide_false_positives !== 'No',
  ai_summary: f.ai_summary !== 'No',
  requested_by: f.user?.email || f.user?.name || '',
  report_id,
  out_dir: `/opt/loot/asm/${engagement}/reports/${report_id}`
} }];

const p = $('Report Params').first().json;
const rows = (n) => $(n).all().map((i) => i.json).filter((r) => r && r.engagement === p.engagement);
const RANK = { critical: 4, high: 3, medium: 2, low: 1, info: 0, unknown: -1 };
const SEVS = ['critical', 'high', 'medium', 'low', 'info'];
const HIDDEN = new Set(['false_positive', 'false-positive', 'fp', 'duplicate', 'invalid', 'not_applicable', 'wont_report']);
const RESOLVED = new Set(['fixed', 'resolved', 'closed', 'remediated', 'mitigated']);
const RISKY = {
  21: 'FTP', 23: 'Telnet', 69: 'TFTP', 111: 'RPCbind', 135: 'MS-RPC', 139: 'NetBIOS', 389: 'LDAP', 445: 'SMB', 873: 'rsync',
  1433: 'MSSQL', 1521: 'Oracle DB', 2049: 'NFS', 2375: 'Docker API (plain)', 2376: 'Docker API', 3306: 'MySQL', 3389: 'RDP',
  5432: 'PostgreSQL', 5900: 'VNC', 5984: 'CouchDB', 5985: 'WinRM', 5986: 'WinRM', 6379: 'Redis', 6443: 'Kubernetes API',
  9200: 'Elasticsearch', 10250: 'Kubelet', 11211: 'Memcached', 27017: 'MongoDB'
};

const scope = rows('Get Scope');
if (!scope.length) throw new Error(`Engagement "${p.engagement}" is not in asm_scope`);
const since = p.since ? new Date(p.since) : null;
const inPeriod = (d) => !since || (d && new Date(d) >= since);
const sev = (s) => (RANK[String(s || '').toLowerCase()] !== undefined ? String(s).toLowerCase() : 'unknown');
const minRank = RANK[p.min_severity] ?? RANK.low;

const runs = rows('Get Runs').sort((a, b) => String(b.started).localeCompare(String(a.started)));
const periodRuns = runs.filter((r) => inPeriod(r.started));
const assets = rows('Get Assets');

const remediation = (f) => {
  const t = `${f.source} ${f.template_id} ${f.name}`.toLowerCase();
  if (f.source === 'takeover' || t.includes('takeover')) return 'Remove or repoint the dangling DNS record, or reclaim the third-party resource it points to.';
  if (f.source === 'cve-watch' || /cve-\d{4}-\d+/.test(t)) return 'Confirm the running version and apply the vendor patch or upgrade. Prioritise anything on the CISA KEV list.';
  if (t.includes('default-login') || t.includes('default login')) return 'Change default credentials, restrict the interface to trusted networks and enforce MFA where supported.';
  if (f.source === 'dalfox' || t.includes('xss')) return 'Apply context-aware output encoding and input validation; deploy a restrictive Content-Security-Policy.';
  if (f.source === 'ffuf' || /\.git|\.env|backup|actuator|swagger|exposure/.test(t)) return 'Remove the file or endpoint from the web root, or restrict it with authentication or network controls. Rotate any secrets it exposed.';
  if (t.includes('misconfig')) return 'Harden the service configuration in line with vendor guidance.';
  return 'Validate the finding and remediate in line with vendor guidance.';
};
const confidence = (f) => {
  const note = String(f.triage_note || '').toLowerCase();
  if (note.includes('version not confirmed') || note.includes('unversioned')) return 'Unconfirmed';
  if (f.triage_fp_likelihood != null && f.triage_fp_likelihood >= 80) return 'Low';
  if (f.source === 'cve-watch') return 'Version match';
  return 'Detected';
};

const all = rows('Get Findings').map((f) => ({
  ...f,
  severity: sev(f.severity),
  status: String(f.status || 'new').toLowerCase(),
  confidence: confidence(f),
  remediation: remediation(f),
  is_new: inPeriod(f.first_seen)
}));
const visible = all.filter((f) => !(p.hide_fp && HIDDEN.has(f.status)));
const resolved = visible.filter((f) => RESOLVED.has(f.status));
const open = visible
  .filter((f) => !RESOLVED.has(f.status) && (RANK[f.severity] ?? -1) >= minRank)
  .sort((a, b) => (RANK[b.severity] ?? -1) - (RANK[a.severity] ?? -1) || String(a.host).localeCompare(String(b.host)));

const bySev = Object.fromEntries(SEVS.map((s) => [s, open.filter((f) => f.severity === s).length]));
const rated = open.filter((f) => f.confidence !== 'Low');
const worst = SEVS.find((s) => s !== 'info' && rated.some((f) => f.severity === s));
const rating = worst ? worst.charAt(0).toUpperCase() + worst.slice(1) : 'Low';

const ports = assets.filter((a) => a.kind === 'port').sort((a, b) => String(a.ip).localeCompare(String(b.ip)) || a.port - b.port);
const web = assets.filter((a) => a.kind === 'web').sort((a, b) => String(a.url).localeCompare(String(b.url)));
const hostSet = new Set();
for (const a of assets) for (const h of [a.host, a.ip]) if (h) hostSet.add(h);
const ipSet = new Set(assets.map((a) => a.ip).filter(Boolean));
const exposures = ports.filter((a) => RISKY[a.port]).map((a) => ({ ip: a.ip, host: a.host, port: a.port, label: RISKY[a.port], service: a.service }));

const techCount = {};
for (const w of web) for (const t of String(w.tech || '').split(/[,;|]/).map((s) => s.trim()).filter(Boolean)) techCount[t] = (techCount[t] || 0) + 1;
const tech = Object.entries(techCount).sort((a, b) => b[1] - a[1]).slice(0, 20).map(([name, count]) => ({ name, count }));

const report = {
  report_id: p.report_id,
  engagement: p.engagement,
  client_name: p.client_name,
  generated: new Date().toISOString(),
  period_days: p.period_days,
  since: p.since,
  min_severity: p.min_severity,
  rating,
  scope: scope.map((s) => ({ asset: s.asset, type: s.asset_type || '', exclude: !!s.exclude, enabled: !!s.enabled })),
  scope_start: scope.map((s) => s.scope_start).filter(Boolean).sort()[0] || null,
  scope_end: scope.map((s) => s.scope_end).filter(Boolean).sort().slice(-1)[0] || null,
  intrusive: scope.filter((s) => !s.exclude).every((s) => s.allow_intrusive === true),
  stats: {
    hosts: hostSet.size,
    ips: ipSet.size,
    ports: ports.length,
    web: web.length,
    runs_total: runs.length,
    runs_period: periodRuns.length,
    runs_ok: periodRuns.filter((r) => r.status === 'ok').length,
    last_run: runs[0]?.finished || runs[0]?.started || null,
    first_run: runs.length ? runs[runs.length - 1].started : null,
    assets_new_period: assets.filter((a) => inPeriod(a.first_seen)).length,
    findings_open: open.length,
    findings_new_period: open.filter((f) => f.is_new).length,
    findings_resolved: resolved.length,
    by_severity: bySev
  },
  findings: open.map((f) => ({
    severity: f.severity, name: f.name || f.template_id, template_id: f.template_id, source: f.source, host: f.host,
    location: f.matched_at || f.url, status: f.status, confidence: f.confidence, remediation: f.remediation,
    note: f.triage_note || '', first_seen: f.first_seen, last_seen: f.last_seen, is_new: f.is_new, evidence_dir: f.evidence_dir
  })),
  resolved: resolved.map((f) => ({ severity: f.severity, name: f.name || f.template_id, host: f.host, status: f.status, last_seen: f.last_seen })),
  exposures,
  ports: ports.map((a) => ({ ip: a.ip, host: a.host, port: a.port, service: a.service, first_seen: a.first_seen, last_seen: a.last_seen })),
  web: web.map((a) => ({ url: a.url, status_code: a.status_code, title: a.title, tech: a.tech, first_seen: a.first_seen, last_seen: a.last_seen })),
  tech,
  runs: periodRuns.slice(0, 50).map((r) => ({ run_id: r.run_id, trigger: r.trigger, status: r.status, started: r.started, finished: r.finished, hosts: r.hosts, assets_new: r.assets_new, assets_changed: r.assets_changed, findings_new: r.findings_new }))
};

const facts = [
  `Client: ${report.client_name}`,
  `Reporting period: ${p.period_days ? `last ${p.period_days} days` : 'all time'}`,
  `Overall rating: ${rating}`,
  `Assets: ${report.stats.hosts} hosts/IPs, ${report.stats.ports} open ports, ${report.stats.web} web endpoints`,
  `Open findings by severity: ${SEVS.map((s) => `${s} ${bySev[s]}`).join(', ')}`,
  `New findings this period: ${report.stats.findings_new_period}; resolved: ${report.stats.findings_resolved}`,
  `Exposed sensitive services: ${exposures.length ? exposures.slice(0, 15).map((e) => `${e.label} on ${e.ip}:${e.port}`).join('; ') : 'none'}`,
  'Top findings:',
  ...open.filter((f) => f.severity !== 'info').slice(0, 15).map((f) => `- [${f.severity}] ${f.name || f.template_id} on ${f.host} (confidence: ${f.confidence})`)
].join('\n');

const SYSTEM = [
  'You write the executive summary of an external attack surface management report for a client of a penetration testing consultancy.',
  'Audience: non-technical leadership. Use British English. Be factual and measured: only use the facts given, never invent assets, numbers or findings.',
  'Where a finding has confidence "Unconfirmed", say it needs verification rather than stating it as fact.',
  'Reply with JSON only, exactly this shape:',
  '{"summary": "<two or three short paragraphs separated by \\n\\n, max 220 words in total>", "priorities": ["<up to 5 short prioritised actions>"]}'
].join('\n');

return [{ json: {
  report,
  ollama: {
    model: 'OLLAMA_MODEL',
    stream: false,
    think: false,
    format: 'json',
    keep_alive: '15m',
    options: { temperature: 0.2, num_predict: 700 },
    messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: facts }]
  }
} }];

const r = $('Build Report Data').first().json.report;
const p = $('Report Params').first().json;
const SEVS = ['critical', 'high', 'medium', 'low', 'info'];
const COLOUR = { critical: '#7b1020', high: '#c0392b', medium: '#d68910', low: '#2e86c1', info: '#7f8c8d', unknown: '#7f8c8d' };
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const day = (d) => (d ? new Date(d).toISOString().slice(0, 10) : '');
const cap = (s) => String(s).charAt(0).toUpperCase() + String(s).slice(1);
const pill = (s) => `<span class="pill" style="background:${COLOUR[s] || COLOUR.unknown}">${esc(cap(s))}</span>`;
const csvCell = (v) => { const s = String(v ?? ''); return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csv = (cols, rows) => [cols.join(','), ...rows.map((x) => cols.map((c) => csvCell(x[c])).join(','))].join('\r\n') + '\r\n';
const s = r.stats;
const n = (c, one, many) => `${c} ${c === 1 ? one : many}`;

let summary = '';
let priorities = [];
let aiUsed = false;
const raw = $input.first().json?.message?.content;
if (raw) {
  try {
    const m = String(raw).match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(m ? m[0] : raw);
    summary = String(parsed.summary || '').trim();
    priorities = (Array.isArray(parsed.priorities) ? parsed.priorities : []).map((x) => String(x).trim()).filter(Boolean).slice(0, 5);
    aiUsed = !!summary;
  } catch (e) {}
}
if (!summary) {
  const sevLine = SEVS.filter((x) => x !== 'info' && s.by_severity[x]).map((x) => `${s.by_severity[x]} ${x}`).join(', ');
  summary = [
    `During ${r.period_days ? `the last ${r.period_days} days` : 'the monitoring period'} we continuously monitored the external attack surface of ${r.client_name}. ` +
      `${n(s.runs_period, 'automated assessment run was', 'automated assessment runs were')} completed, covering ${n(s.hosts, 'host or IP address', 'hosts and IP addresses')}, ${n(s.ports, 'open network port', 'open network ports')} and ${n(s.web, 'web endpoint', 'web endpoints')}.`,
    sevLine
      ? `There ${s.findings_open === 1 ? 'is' : 'are'} currently ${n(s.findings_open, 'open finding', 'open findings')} (${sevLine}), of which ${s.findings_new_period} ${s.findings_new_period === 1 ? 'was' : 'were'} first identified during this period. The overall external risk rating is ${r.rating}.`
      : `No findings of low severity or above are currently open. The overall external risk rating is ${r.rating}.`,
    r.exposures.length
      ? `${r.exposures.length} sensitive service${r.exposures.length === 1 ? ' is' : 's are'} reachable from the internet and should be reviewed to confirm the exposure is intended.`
      : 'No commonly targeted management or database services were found exposed to the internet.'
  ].join('\n\n');
}
if (!priorities.length) {
  priorities = r.findings.filter((f) => ['critical', 'high'].includes(f.severity)).slice(0, 3).map((f) => `${f.name} on ${f.host}: ${f.remediation}`);
  if (r.exposures.length) priorities.push(`Review the ${r.exposures.length} exposed sensitive service${r.exposures.length === 1 ? '' : 's'} and restrict access to trusted networks.`);
  if (!priorities.length) priorities.push('Maintain continuous monitoring and review new assets as they appear.');
}

const findingRows = r.findings.map((f, i) => `
<tr>
  <td>F-${String(i + 1).padStart(3, '0')}</td>
  <td>${pill(f.severity)}</td>
  <td><strong>${esc(f.name)}</strong>${f.is_new ? ' <span class="new">NEW</span>' : ''}<div class="muted">${esc(f.template_id)} · ${esc(f.source)}</div></td>
  <td class="mono">${esc(f.host)}<div class="muted break">${esc(f.location)}</div></td>
  <td>${esc(f.confidence)}</td>
  <td>${esc(day(f.first_seen))}</td>
</tr>`).join('');

const detail = r.findings.filter((f) => f.severity !== 'info').map((f, i) => `
<div class="finding" style="border-left-color:${COLOUR[f.severity]}">
  <h3>F-${String(r.findings.indexOf(f) + 1).padStart(3, '0')} · ${esc(f.name)} ${pill(f.severity)}</h3>
  <table class="kv">
    <tr><th>Affected asset</th><td class="mono break">${esc(f.location || f.host)}</td></tr>
    <tr><th>Detection</th><td>${esc(f.source)} / ${esc(f.template_id)}</td></tr>
    <tr><th>Confidence</th><td>${esc(f.confidence)}</td></tr>
    <tr><th>First / last seen</th><td>${esc(day(f.first_seen))} / ${esc(day(f.last_seen))}</td></tr>
    <tr><th>Status</th><td>${esc(cap(f.status))}</td></tr>
    ${f.note ? `<tr><th>Notes</th><td>${esc(f.note)}</td></tr>` : ''}
    <tr><th>Recommendation</th><td>${esc(f.remediation)}</td></tr>
  </table>
</div>`).join('');

const sevBars = SEVS.map((x) => {
  const max = Math.max(1, ...SEVS.map((y) => s.by_severity[y]));
  return `<div class="bar"><span class="lbl">${cap(x)}</span><span class="track"><span class="fill" style="width:${(s.by_severity[x] / max) * 100}%;background:${COLOUR[x]}"></span></span><span class="num">${s.by_severity[x]}</span></div>`;
}).join('');

const table = (cols, rows, empty) => rows.length
  ? `<table class="grid"><thead><tr>${cols.map((c) => `<th>${esc(c[0])}</th>`).join('')}</tr></thead><tbody>${rows.map((x) => `<tr>${cols.map((c) => `<td class="${c[2] || ''}">${c[1](x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`
  : `<p class="muted">${esc(empty)}</p>`;

const html = `<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(r.client_name)} · External Attack Surface Report</title>
<style>
@page { size: A4; margin: 16mm 14mm; }
:root { --ink:#1c2430; --muted:#5d6b7a; --line:#dfe4ea; --accent:#1f3a5f; --bg:#ffffff; --soft:#f4f6f9; }
* { box-sizing: border-box; }
body { margin:0; background:var(--bg); color:var(--ink); font:10.5pt/1.5 -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; }
main { max-width: 1000px; margin: 0 auto; padding: 24px 16px; }
h1 { font-size: 26pt; margin: 0 0 4px; color: var(--accent); }
h2 { font-size: 15pt; color: var(--accent); border-bottom: 2px solid var(--accent); padding-bottom: 4px; margin: 28px 0 12px; break-after: avoid; }
h3 { font-size: 11.5pt; margin: 0 0 8px; }
.cover { min-height: 60vh; break-after: page; display:flex; flex-direction:column; justify-content:center; border-bottom: 6px solid var(--accent); margin-bottom: 24px; }
.cover .sub { font-size: 14pt; color: var(--muted); }
.meta { margin-top: 24px; color: var(--muted); }
.conf { margin-top: 32px; font-size: 9pt; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; }
.cards { display:grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; margin: 12px 0; }
.card { background: var(--soft); border-radius: 6px; padding: 10px 12px; }
.card .v { font-size: 18pt; font-weight: 700; color: var(--accent); }
.card .k { font-size: 8.5pt; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; }
.rating { display:inline-block; padding: 4px 14px; border-radius: 4px; color:#fff; font-weight:700; }
.pill { display:inline-block; color:#fff; border-radius: 3px; padding: 0 6px; font-size: 8.5pt; font-weight: 600; vertical-align: middle; }
.new { color:#c0392b; font-size: 8pt; font-weight:700; }
.muted { color: var(--muted); font-size: 8.5pt; }
.mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 8.5pt; }
.break { word-break: break-all; }
table { border-collapse: collapse; width: 100%; }
.grid th, .grid td { border-bottom: 1px solid var(--line); padding: 5px 6px; text-align:left; vertical-align: top; font-size: 9pt; }
.grid th { background: var(--soft); font-size: 8.5pt; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); }
.grid tr { break-inside: avoid; }
.kv th { width: 150px; text-align:left; color: var(--muted); font-weight: 600; padding: 3px 8px 3px 0; vertical-align: top; font-size: 9pt; }
.kv td { padding: 3px 0; font-size: 9pt; }
.finding { border-left: 4px solid; background: var(--soft); padding: 10px 14px; margin: 10px 0; border-radius: 0 6px 6px 0; break-inside: avoid; }
.bar { display:flex; align-items:center; gap:8px; margin: 3px 0; }
.bar .lbl { width: 70px; font-size: 9pt; }
.bar .track { flex:1; background: var(--soft); height: 12px; border-radius: 3px; overflow:hidden; }
.bar .fill { display:block; height:100%; }
.bar .num { width: 30px; text-align:right; font-weight:600; }
.summary p { margin: 0 0 10px; }
ol li { margin-bottom: 4px; }
.pb { break-before: page; }
.foot { margin-top: 32px; border-top: 1px solid var(--line); padding-top: 8px; font-size: 8pt; color: var(--muted); }
@media screen and (max-width: 640px) { .grid { display:block; overflow-x:auto; } .kv th { width: 110px; } h1 { font-size: 20pt; } }
@media (prefers-color-scheme: dark) { @media screen { :root { --ink:#e3e8ef; --muted:#9aa8b8; --line:#2c3644; --accent:#8fb8e8; --bg:#11161d; --soft:#1a212b; } } }
@media print { .cover { min-height: 240mm; border-bottom: 0; border-left: 8px solid var(--accent); padding-left: 24px; } .cards { grid-template-columns: repeat(3, 1fr); } }
</style></head><body><main>

<section class="cover">
  <div class="conf">Confidential · Prepared for ${esc(r.client_name)}</div>
  <h1>External Attack Surface Report</h1>
  <div class="sub">${esc(r.client_name)}</div>
  <div class="meta">
    Reporting period: ${r.since ? `${esc(day(r.since))} to ${esc(day(r.generated))}` : `All monitoring to ${esc(day(r.generated))}`}<br>
    Report reference: ${esc(r.engagement)}/${esc(r.report_id)}<br>
    Generated: ${esc(r.generated.replace('T', ' ').slice(0, 16))} UTC
  </div>
</section>

<h2>1. Executive summary</h2>
<p>Overall external risk rating: <span class="rating" style="background:${COLOUR[r.rating.toLowerCase()] || COLOUR.low}">${esc(r.rating)}</span></p>
<div class="summary">${summary.split(/\n{2,}/).map((x) => `<p>${esc(x)}</p>`).join('')}</div>
<div class="cards">
  <div class="card"><div class="v">${s.hosts}</div><div class="k">Hosts and IPs</div></div>
  <div class="card"><div class="v">${s.ports}</div><div class="k">Open ports</div></div>
  <div class="card"><div class="v">${s.web}</div><div class="k">Web endpoints</div></div>
  <div class="card"><div class="v">${s.findings_open}</div><div class="k">Open findings</div></div>
  <div class="card"><div class="v">${s.findings_new_period}</div><div class="k">New this period</div></div>
  <div class="card"><div class="v">${s.runs_period}</div><div class="k">Assessment runs</div></div>
</div>
<h3>Open findings by severity</h3>
${sevBars}
<h3 style="margin-top:16px">Priority actions</h3>
<ol>${priorities.map((x) => `<li>${esc(x)}</li>`).join('')}</ol>
${aiUsed ? '<p class="muted">The narrative summary was drafted with the assistance of a locally hosted language model and reviewed against the underlying data.</p>' : ''}

<h2 class="pb">2. Scope and methodology</h2>
<p>The following assets were in scope. Excluded assets were removed from every stage of testing.</p>
${table([['Asset', (x) => esc(x.asset), 'mono'], ['Type', (x) => esc(x.type || 'auto')], ['Treatment', (x) => (x.exclude ? 'Excluded' : 'In scope')]], r.scope, 'No scope recorded.')}
<p>${r.scope_start || r.scope_end ? `Authorised testing window: ${esc(day(r.scope_start) || 'open')} to ${esc(day(r.scope_end) || 'open')}. ` : ''}Intrusive checks were ${r.intrusive ? 'authorised' : '<strong>not</strong> authorised'} for this engagement.</p>
<p>Monitoring is automated and repeats several times a day. Each run enumerates subdomains from passive sources and DNS resolution, filters every result back through the agreed scope, identifies shared and CDN-fronted infrastructure so that third-party systems are not tested, scans the most common 1,000 TCP ports on in-scope addresses, fingerprints web services, and compares the result with the previous run. Vulnerability checks are then run only against new or changed assets, using curated templates for known CVEs, exposures, misconfigurations, default credentials and subdomain takeover. Fingerprinted software versions are also matched daily against the NVD and the CISA Known Exploited Vulnerabilities catalogue. Denial-of-service and fuzzing checks are never run.</p>
<p>Findings show a confidence level: <em>Detected</em> means a check matched the live service, <em>Version match</em> means the observed version falls in the vulnerable range, <em>Unconfirmed</em> means the product matched but the version could not be verified, and <em>Low</em> means automated triage considers it likely to be a false positive.</p>

